  { $match: { _id: 'electronics' } },
  { $graphLookup: {
      from: 'categories',
      startWith: '$parentId',
      connectFromField: 'parentId',
      connectToField: '_id',
      as: 'ancestors',
      maxDepth: 5,
      depthField: 'depth',
  } },
]);
